package com.example.sqlite;

import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.os.Bundle;
import android.view.Gravity;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.Spinner;
import android.widget.TextView;
import android.widget.Toast;
import androidx.appcompat.app.AlertDialog;
import androidx.appcompat.app.AppCompatActivity;
import java.util.ArrayList;

public class AdminActivity extends AppCompatActivity {
 private DBHelper helper;
 @Override protected void onCreate(Bundle b){super.onCreate(b);SessionStore session=new SessionStore(this);if(!session.active()||!session.role().equalsIgnoreCase("Administrador")){finish();return;}helper=new DBHelper(this);setContentView(R.layout.activity_admin);findViewById(R.id.btnNewUser).setOnClickListener(v->newUser());findViewById(R.id.btnListUsers).setOnClickListener(v->users());findViewById(R.id.btnNewRole).setOnClickListener(v->newRole());findViewById(R.id.btnListRoles).setOnClickListener(v->roles());findViewById(R.id.btnNewCategory).setOnClickListener(v->newCategory());findViewById(R.id.btnListCategories).setOnClickListener(v->categories());findViewById(R.id.btnNewSupplier).setOnClickListener(v->newSupplier());findViewById(R.id.btnListSuppliers).setOnClickListener(v->suppliers());}
 private EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);return e;}
 private void newUser(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);EditText name=field("Nombre completo"),user=field("Nombre de usuario"),pass=field("Contraseña");pass.setInputType(129);Spinner role=new Spinner(this);ArrayList<Long> ids=new ArrayList<>();ArrayList<String> names=new ArrayList<>();SQLiteDatabase db=helper.getReadableDatabase();try(Cursor c=db.rawQuery("SELECT id_rol,nombre_rol FROM ROL WHERE activo=1 ORDER BY nombre_rol",null)){while(c.moveToNext()){ids.add(c.getLong(0));names.add(c.getString(1));}}db.close();role.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));box.addView(name);box.addView(user);box.addView(pass);box.addView(role);new AlertDialog.Builder(this).setTitle("Nuevo usuario").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{if(ids.isEmpty()||name.getText().toString().trim().isEmpty()||user.getText().toString().trim().isEmpty()||pass.getText().length()<4)throw new Exception();android.content.ContentValues v=new android.content.ContentValues();v.put("nombre_completo",name.getText().toString().trim());v.put("username",user.getText().toString().trim());v.put("password_hash",DBHelper.hash(pass.getText().toString()));v.put("id_rol",ids.get(role.getSelectedItemPosition()));v.put("activo",1);SQLiteDatabase x=helper.getWritableDatabase();x.insertOrThrow("USUARIO",null,v);x.close();toast("Usuario registrado.");}catch(Exception e){toast("No se guardó. Completa los campos y usa un nombre de usuario único.");}}).show();}
 private void newRole(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);EditText name=field("Nombre único del rol"),desc=field("Descripción");box.addView(name);box.addView(desc);new AlertDialog.Builder(this).setTitle("Nuevo rol").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{if(name.getText().toString().trim().isEmpty())throw new Exception();android.content.ContentValues v=new android.content.ContentValues();v.put("nombre_rol",name.getText().toString().trim());v.put("descripcion",desc.getText().toString().trim());SQLiteDatabase db=helper.getWritableDatabase();db.insertOrThrow("ROL",null,v);db.close();toast("Rol registrado.");}catch(Exception e){toast("El nombre del rol es obligatorio y único.");}}).show();}
 private void newCategory(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);EditText name=field("Nombre de categoría"),desc=field("Descripción opcional");box.addView(name);box.addView(desc);new AlertDialog.Builder(this).setTitle("Nueva categoría").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{if(name.getText().toString().trim().isEmpty())throw new Exception();android.content.ContentValues v=new android.content.ContentValues();v.put("nombre_categoria",name.getText().toString().trim());v.put("descripcion",desc.getText().toString().trim());SQLiteDatabase db=helper.getWritableDatabase();db.insertOrThrow("CATEGORIA",null,v);db.close();toast("Categoría registrada.");}catch(Exception e){toast("El nombre es obligatorio y no puede repetirse.");}}).show();}
 private void newSupplier(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);EditText rut=field("RUT de empresa"),name=field("Razón social"),contact=field("Número de contacto");box.addView(rut);box.addView(name);box.addView(contact);new AlertDialog.Builder(this).setTitle("Nuevo proveedor").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{if(rut.getText().toString().trim().isEmpty()||name.getText().toString().trim().isEmpty()||contact.getText().toString().trim().isEmpty())throw new Exception();android.content.ContentValues v=new android.content.ContentValues();v.put("rut_empresa",rut.getText().toString().trim());v.put("razon_social",name.getText().toString().trim());v.put("contacto",contact.getText().toString().trim());SQLiteDatabase db=helper.getWritableDatabase();db.insertOrThrow("PROVEEDOR",null,v);db.close();toast("Proveedor registrado.");}catch(Exception e){toast("Completa todos los datos y usa un RUT único.");}}).show();}
 private void users(){ArrayList<String> rows=new ArrayList<>();ArrayList<Long> ids=new ArrayList<>();SQLiteDatabase db=helper.getReadableDatabase();try(Cursor c=db.rawQuery("SELECT U.id_usuario,U.nombre_completo,U.username,R.nombre_rol,U.activo FROM USUARIO U JOIN ROL R ON R.id_rol=U.id_rol ORDER BY U.nombre_completo",null)){while(c.moveToNext()){ids.add(c.getLong(0));rows.add(c.getString(1)+" · @"+c.getString(2)+" · "+c.getString(3)+" · "+(c.getInt(4)==1?"Activo":"Inactivo"));}}db.close();showList("Usuarios · toca para activar/desactivar",rows,i->{SQLiteDatabase x=helper.getWritableDatabase();x.execSQL("UPDATE USUARIO SET activo=CASE activo WHEN 1 THEN 0 ELSE 1 END WHERE id_usuario=?",new Object[]{ids.get(i)});x.close();users();});}
 private void roles(){ArrayList<String> rows=new ArrayList<>();ArrayList<Long> ids=new ArrayList<>();SQLiteDatabase db=helper.getReadableDatabase();try(Cursor c=db.rawQuery("SELECT id_rol,nombre_rol,descripcion,activo FROM ROL ORDER BY nombre_rol",null)){while(c.moveToNext()){ids.add(c.getLong(0));rows.add(c.getString(1)+" · "+c.getString(2)+" · "+(c.getInt(3)==1?"Activo":"Inactivo"));}}db.close();showList("Roles · toca para activar/desactivar",rows,i->{SQLiteDatabase x=helper.getWritableDatabase();x.execSQL("UPDATE ROL SET activo=CASE activo WHEN 1 THEN 0 ELSE 1 END WHERE id_rol=? AND nombre_rol!='Administrador'",new Object[]{ids.get(i)});x.close();roles();});}
 private void categories(){ArrayList<String> rows=new ArrayList<>();ArrayList<Long> ids=new ArrayList<>();SQLiteDatabase db=helper.getReadableDatabase();try(Cursor c=db.rawQuery("SELECT id_categoria,nombre_categoria,descripcion,activo FROM CATEGORIA ORDER BY nombre_categoria",null)){while(c.moveToNext()){ids.add(c.getLong(0));rows.add(c.getString(1)+" · "+c.getString(2)+" · "+(c.getInt(3)==1?"Activa":"Inactiva"));}}db.close();showList("Categorías · toca para activar/desactivar",rows,i->{SQLiteDatabase x=helper.getWritableDatabase();x.execSQL("UPDATE CATEGORIA SET activo=CASE activo WHEN 1 THEN 0 ELSE 1 END WHERE id_categoria=?",new Object[]{ids.get(i)});x.close();categories();});}
 private void suppliers(){ArrayList<String> rows=new ArrayList<>();SQLiteDatabase db=helper.getReadableDatabase();try(Cursor c=db.rawQuery("SELECT rut_empresa,razon_social,contacto,activo FROM PROVEEDOR ORDER BY razon_social",null)){while(c.moveToNext())rows.add(c.getString(1)+" · RUT "+c.getString(0)+" · "+c.getString(2)+" · "+(c.getInt(3)==1?"Activo":"Inactivo"));}db.close();showList("Proveedores",rows,null);}
 private interface Select{void on(int i);}private void showList(String title,ArrayList<String> rows,Select click){if(rows.isEmpty()){toast("No hay registros todavía.");return;}new AlertDialog.Builder(this).setTitle(title).setItems(rows.toArray(new String[0]),(d,i)->{if(click!=null)click.on(i);}).setPositiveButton("Cerrar",null).show();}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}@Override protected void onDestroy(){helper.close();super.onDestroy();}
}

